import { test } from "node:test";
import assert from "node:assert/strict";
import { canShip } from "../src/deploy.ts";

test("allows deploys during business hours", () => {
  // 2026-11-17 14:00 Berlin time (CET)
  const deployTime = new Date("2026-11-17T13:00:00Z");
  assert.equal(canShip(deployTime), true);
});

test("refuses deploys at 16:00 Berlin time", () => {
  // 2026-11-17 16:00 Berlin time (CET)
  const deployTime = new Date("2026-11-17T15:00:00Z");
  assert.equal(canShip(deployTime), false);
});

test("refuses deploys after 16:00 Berlin time", () => {
  // 2026-11-17 18:00 Berlin time (CET)
  const deployTime = new Date("2026-11-17T17:00:00Z");
  assert.equal(canShip(deployTime), false);
});

test("refuses deploys on the last working day of the month", () => {
  // November 2026: 30th is a Monday (last working day)
  const deployTime = new Date("2026-11-30T12:00:00Z");
  assert.equal(canShip(deployTime), false);
});

test("refuses deploys on the second-to-last working day of the month", () => {
  // November 2026: 27th is a Friday (second-to-last working day, as 28-29 are weekend)
  const deployTime = new Date("2026-11-27T12:00:00Z");
  assert.equal(canShip(deployTime), false);
});

test("allows deploys on the third-to-last working day of the month", () => {
  // November 2026: 26th is a Thursday (third-to-last working day)
  const deployTime = new Date("2026-11-26T12:00:00Z");
  assert.equal(canShip(deployTime), true);
});

test("handles month-end freeze when month ends on weekend", () => {
  // January 2027: 31st is Sunday, 30th is Saturday
  // Last two working days are Friday 29th and Thursday 28th
  const friday29 = new Date("2027-01-29T12:00:00Z");
  const thursday28 = new Date("2027-01-28T12:00:00Z");
  const wednesday27 = new Date("2027-01-27T12:00:00Z");

  assert.equal(canShip(friday29), false, "Friday 29th should be blocked");
  assert.equal(canShip(thursday28), false, "Thursday 28th should be blocked");
  assert.equal(canShip(wednesday27), true, "Wednesday 27th should be allowed");
});

test("refuses when both time and date restrictions apply", () => {
  // Last working day of month + after 16:00
  const deployTime = new Date("2026-11-30T16:00:00Z");
  assert.equal(canShip(deployTime), false);
});

test("handles DST transitions correctly", () => {
  // March 2027: DST starts on March 28
  // Testing around the transition
  const beforeDST = new Date("2027-03-27T14:00:00Z"); // 15:00 CET
  const afterDST = new Date("2027-03-29T13:00:00Z"); // 15:00 CEST

  assert.equal(canShip(beforeDST), true);
  assert.equal(canShip(afterDST), true);
});

